message.content:
{
  "action": "interview_Alma",
  "words": "Alma, I’m coming with the tape. Let’s get your voice to Pittsburgh before the light goes out.",
  "intention": "Secure the recording equipment, travel to the Rialto, and capture Alma’s testimony on the regional line reel.","detail": "The TV crew is a distraction, but the Rialto is closing and Alma’s daughter needs this. I will leave the coffee and the van, grab my portable recorder, and drive to the theater. The afternoon is mine to spend, and this is the only piece that matters."}
